// ─────────────────────────────────────────────────────────────────────────────
//  CERCA I CALCULADORES
// ─────────────────────────────────────────────────────────────────────────────

const deacc = s =>
  (s || '').normalize('NFD').replace(/[\u0300-\u036f]/g, '').toLowerCase();

const HAYSTACK = new WeakMap();

function haystack(inf) {
  let h = HAYSTACK.get(inf);
  if (!h) {
    h = deacc([inf.title, inf.article, inf.code, inf.block, inf.sub, inf.note,
               ...(inf.keywords || [])].filter(Boolean).join(' '));
    HAYSTACK.set(inf, h);
  }
  return h;
}

/**
 * Tot el que és cercable: el catàleg de trànsit del SCT més els supòsits de
 * seguretat ciutadana, que queden fora del catàleg però es consulten igual.
 */
export const TOTES_INFRACCIONS = [...INFRACTIONS, ...INFRACCIONS_SEGURETAT_CIUTADANA];

/** Filtres disponibles a la pantalla d'infraccions. */
export const FILTRES = [
  { id: 'totes', label: 'Totes', test: () => true },
  { id: 'mg', label: 'Molt greus', test: i => i.sev === 'mg' || i.sev === 'gmg' },
  { id: 'g', label: 'Greus', test: i => i.sev === 'g' || i.sev === 'gmg' },
  { id: 'l', label: 'Lleus', test: i => i.sev === 'l' },
  { id: 'punts', label: 'Amb punts', test: i => i.points > 0 },
  { id: 'trlsv', label: 'LSV', test: i => i.norm === 'trlsv' },
  { id: 'rgc', label: 'RGC', test: i => i.norm === 'rgc' },
  { id: 'rgcond', label: 'Conductors', test: i => i.norm === 'rgcond' },
  { id: 'rgv', label: 'Vehicles', test: i => i.norm === 'rgv' },
  { id: 'lrcscvm', label: 'Assegurança', test: i => i.norm === 'lrcscvm' },
  { id: 'repc', label: 'Autoescoles', test: i => i.norm === 'repc' },
  { id: 'lo42015', label: 'Seg. ciutadana', test: i => i.norm === 'lo42015' },
];

export function searchInfractions(query = '', filter = 'totes') {
  const f = FILTRES.find(x => x.id === filter) || FILTRES[0];
  const q = deacc(query.trim());
  const terms = q ? q.split(/\s+/) : [];
  return TOTES_INFRACCIONS.filter(inf => {
    if (!f.test(inf)) return false;
    if (!terms.length) return true;
    const h = haystack(inf);
    return terms.every(t => h.includes(t));
  });
}

export function findInfraction(id) {
  return TOTES_INFRACCIONS.find(i => i.id === id) || null;
}

/**
 * Sanció per excés de velocitat segons el barem annex del RGC.
 * @param {number} limit    límit de la via en km/h
 * @param {number} mesurada velocitat mesurada en km/h
 * @returns {{penal?: true, article?: string, avis?: string,
 *            sev?: 'g'|'mg', fine?: number, punts?: number, tram?: string}|null}
 */
export function sancioVelocitat(limit, mesurada, viaUrbana = false) {
  const col = BAREM_VELOCITAT.limits.indexOf(Number(limit));
  if (col < 0 || !Number.isFinite(mesurada)) return null;

  // El llindar penal depèn del tipus de via: cal saber si és urbana.
  const llindar = viaUrbana
    ? LLINDAR_PENAL_VELOCITAT.urba
    : LLINDAR_PENAL_VELOCITAT.interurba;
  if (mesurada - limit > llindar) {
    return {
      penal: true,
      article: LLINDAR_PENAL_VELOCITAT.article,
      excess: mesurada - limit,
      llindar,
      via: viaUrbana ? 'urbana' : 'interurbana',
      avis: LLINDAR_PENAL_VELOCITAT.avis,
    };
  }

  for (const band of BAREM_VELOCITAT.bands) {
    const from = band.from[col];
    const to = band.to[col];
    if (mesurada >= from && (to === null || mesurada <= to)) {
      return {
        sev: to === null ? 'mg' : 'g',
        fine: band.fine,
        fine50: Math.round(band.fine / 2),
        punts: band.punts,
        tram: to === null ? `superior a ${from - 1} km/h` : `${from}–${to} km/h`,
        nota: BAREM_VELOCITAT.nota,
      };
    }
  }
  return { senseInfraccio: true }; // per sota del primer tram del barem
}

/**
 * Sanció per alcoholèmia segons el barem del catàleg.
 * @param {number} mgL       taxa en mg/l d'aire espirat
 * @param {string} perfilId  'general' | 'professional' | 'menor-novell' | 'menor-experimentat' | 'menor'
 * @param {boolean} reincident sancionat l'any immediatament anterior per la taxa
 */
const fmtTaxa = n => n.toFixed(2).replace('.', ',');

export function sancioAlcohol(mgL, perfilId = 'general', reincident = false) {
  if (!Number.isFinite(mgL)) return null;
  if (mgL >= LLINDAR_PENAL_ALCOHOL.aireEspirat) {
    return { penal: true, ...LLINDAR_PENAL_ALCOHOL };
  }

  let perfil = BAREM_ALCOHOL.perfils.find(p => p.id === perfilId);
  let trams = perfil ? perfil.trams : null;
  if (!perfil) {
    for (const p of BAREM_ALCOHOL.perfils) {
      const sub = (p.subperfils || []).find(s => s.id === perfilId);
      if (sub) { perfil = p; trams = sub.trams; break; }
    }
  }
  if (!perfil || !trams) return null;

  if (reincident && perfil.reincident) {
    return { ...perfil.reincident, tram: BAREM_ALCOHOL.reincidencia, perfil: perfil.nom };
  }
  for (const t of trams) {
    if (mgL >= t.from && (t.to === null || mgL <= t.to)) {
      return {
        fine: t.fine,
        fine50: t.fine50,
        punts: t.punts,
        condicional: !!t.condicional,
        tram: t.to === null
          ? `superior a ${fmtTaxa(t.from - 0.01)} mg/l`
          : `${fmtTaxa(t.from)}–${fmtTaxa(t.to)} mg/l`,
        perfil: perfil.nom,
        nota: t.condicional ? BAREM_ALCOHOL.notaCondicional : undefined,
      };
    }
  }
  return { senseInfraccio: true }; // taxa per sota del primer tram d'aquest perfil
}
